WFJ.Data.add("gossip", {
  ["6d0fc9d772138ed0"] = { "Si dice in giro che abbiamo raccolto tutto quello che ci serve. Ora tutto dipende dall'⟦Horde=Orda⟧, che deve radunare la sua roba. Quando l'avrà fatto, potremo spedire tutte le nostre merci a ⟦Silithus=Silitus⟧ e la guerra potrà cominciare.", "." },
  ["6d185d04c8b7e921"] = { "Ti insegnerei volentieri quando sarà il momento, ma quel momento non è ancora arrivato! Di certo Lalina Summermoon ti guiderà fino ad allora. La trovi alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, a Darnassus.", "." },
  ["6d1e3c8a961e2cfa"] = { "PER IL RE! Ricacciateli indietro, soldati!", "." },
  ["6d1ea455107042f7"] = { "Stammi vicino...", "." },
  ["6d29a81feafdefea"] = { "Scalpellini. . .ehm. . Defias, state in guardia: l'ancora arrugginita affonda stanotte.", "." },
  ["6d2b4a1a0999b795"] = { "Wow, sei fuori di testa, vero?", "." },
  ["6d2b7cbb9f142cf4"] = { "Colpisci!", "." },
  ["6d305e5741917b2e"] = { "Edward. Tyler. Preparatevi alla vostra prima prova.", "." },
  ["6d35d93d193a1935"] = { "Alanna passa gran parte della giornata alla Radura dell'Oracolo, dove esercita la sua professione. Se vuoi imparare la professione di incantatore, dovrai andare a cercarla là.", "." },
  ["6d4f0bded25575a8"] = { "Non vedi che ho del lavoro da fare qui?", "." },
  ["6d529a58e771bbf4"] = { "Non credo che tu possieda l'acume mentale necessario per comprendere la natura della magia dei portali.", "." },
  ["6d57ef4634cbaab2"] = { "Sarai incarcerato e processato per tradimento, Windsor. Guarderò con gioia mentre emettono un verdetto di colpevolezza e ti condannano a morte per impiccagione...", "." },
  ["6d5beba3a23b48ee"] = { "Il Brandicenere...", "." },
  ["6d5e7f124d94b543"] = { "Salute, {class}. Sono Tyrande Whisperwind, somma sacerdotessa di Elune.", "." },
  ["6d62129e11a9210d"] = { "Nessuna creatura della foresta può sfuggire a Corand, tale è la sua abilità nel seguire le tracce. Faresti bene ad ascoltare i suoi insegnamenti, se vuoi avere anche solo la metà del suo successo.\n\nTi risparmierò la fatica di rintracciarlo e segnerò la sua posizione sulla tua mappa, là nell'⟦Cenarion Enclave=Enclave Cenariana⟧.", "." },
  ["6d6ca3c7a6619a28"] = { "Guerrieri, capitani, continuate a combattere!", "." },
  ["6d6e3503b283bd2b"] = { "Battere un martello su un'incudine non ti rende un fabbro. Dammi qua e lascia che ti insegni qualcosa prima che ci copri tutti di vergogna.", "." },
  ["6d7038e13ece0df7"] = { "Uff! Non ho nemmeno colpito quel maledetto bersaglio! Quel nano testone probabilmente ha di nuovo usato il fucile come mazza.", "." },
  ["6d71462fba132138"] = { "Coraggio! Il dolore passa, e <le/gli> <donne/uomini> vanno matti per chi ha le cicatrici!", "." },
  ["6d749b2b48cb23b3"] = { "La cassetta di sicurezza dell'⟦SI:7=IR:7⟧ si spalanca. In lontananza si sentono grugniti e voci.", "." },
  ["6d773b40b3a2009a"] = { "Preparati a farti Malownare!", "." },
  ["6d77a9240b18618c"] = { "La fede... Alcuni l'hanno persa, altri l'hanno trovata. Non può essere distrutta né creata.\n\nO forse parli dei paramenti della Fede? L'armatura che i nostri sacerdoti e i guerrieri più devoti indossarono in battaglia contro il Flagello durante l'ultima guerra.\n\nSì, gran parte è andata perduta... Rubata dai demoni di Naxxramas.", "." },
  ["6d7c6d152676eb85"] = { "%s fa bere al rospo un po' dello strano liquido.", "." },
  ["6d807b9a6dc624ac"] = { "Il ponte viene su benissimo. Se manteniamo questo ritmo, sarà pronto per quando le prime forze d'espansione partiranno verso nord.", "." },
  ["6d829a49cfe653e9"] = { "Mmmm, solo un po' di attività in superficie, ma il sole è nel posto giusto. Potrebbe rivelarsi una bella giornata.", "." },
  ["6d86f08553b8d22b"] = { "{name} ha difeso la fattoria meridionale!", "." },
  ["6d87e40578b8ecba"] = { "Forse un giorno Saru Steelfury ti insegnerà a fare un'ascia buona come la mia. Lo trovi alla Burning Anvil, nella ⟦Valley of Honor=Valle dell'Onore⟧, scendendo per il sentiero a destra dopo la Red Canyon Mining.", "." },
  ["6d8c179d320e5185"] = { "Leccapiedi, tutti quanti!", "." },
  ["6d8f15944a432a50"] = { "L'etichetta su questo regalo dice: \"Dai 10 anni in su.\"", "." },
  ["6d94ec63d14130a5"] = { "Cosa potrebbe esserci di peggio della morte?", "." },
  ["6d95ccaae73f47ac"] = { "Ho perso la mia ⟦Band of Vaulted Secrets=Vera dei Segreti Ignoti⟧. Puoi sostituirmela?", "." },
  ["6d993a94f3d5da4f"] = { "Maestro degli ippogrifi", "." },
  ["6d9d79ec090da341"] = { "Mi fanno male i piedi...", "." },
  ["6d9e18e18963aff0"] = { "Udite! Udite! *ansima* Cittadini di ⟦Southshore=Riva del Sud⟧, state in guardia: degli assassini si dirigono verso la nostra bella città!", "." },
  ["6da199b314bda842"] = { "Se insegnassi ai novizi, verrebbero a trovarmi molti più allievi e ci sarebbe un gran baccano. Va' a parlare con Dan Golthas, laggiù. È un tipo un po' intenso, ma ha buone intenzioni ed è un insegnante discreto.", "." },
  ["6da26f0e2c5798c8"] = { "Vuoi fare un giro in grifone, eh? È Gryth Thurden quello con cui devi parlare.\n\nLo trovi sul lato orientale della ⟦Great Forge=Grande Forgia⟧, nel centro di ⟦Ironforge=Forgiardente⟧.", "." },
  ["6db3307c5283dbde"] = { "Prima devi dimostrarmi il tuo valore, poi ti addestrerò.", "." },
  ["6db77c5428b4a4c7"] = { "Ti prego, continua, Zamael.", "." },
  ["6dbde0bd192c5502"] = { "Salute. I nostri pipistrelli sono ben addestrati e ben nutriti. Non ne troverai di più veloci.", "." },
  ["6dc65e9f84631e77"] = { "Mio padre è stato ucciso dalla feccia che abita il calderone. Le mie richieste d'aiuto al magistrato di ⟦Stormwind=Roccavento⟧ sono cadute nel vuoto. No, non vogliono nemmeno ammettere che questa parte del mondo esista, figuriamoci mandare qui il loro prezioso esercito a fare giustizia.\n\nCerco vendetta, {race}, né più né meno. Esiste in questo mondo una causa più ardente?", "." },
  ["6dc70fe9d8c47b85"] = { "La velocità di Owatanka è con te, {name}.", "." },
  ["6dcfaf8a4cbd984e"] = { "È scoraggiante. C'è qualcosa che posso fare per fermare tutto questo?", "." },
  ["6dd122c81309cab8"] = { "SCEGLI ME!!!!!", "." },
  ["6ddc922cfb200ceb"] = { "Rivendare deve essere distrutto!", "." },
  ["6de1c07dcf4e8584"] = { "Anche il «⟦The Arcanist's Cookbook=Libro di Ricette dell'Arcanista⟧» è sparito! È un disastro!", "." },
  ["6dec230d74d07ad1"] = { "{name} attacca! Aiuto!", "." },
  ["6df30640eaeee5e2"] = { "Ti do il benvenuto al ⟦Crossroads=Crocevia⟧, {class}. Mi chiamo Thork, e comando le difese di questo posto in nome del Capoguerra.\n\nTi prego, fa' pure come se fossi a casa tua. Finché ti fai gli affari tuoi, nessuno avrà da ridire se ti prendi un po' di spazio.\n\nQui la nostra sicurezza è minacciata da molti pericoli. Se conosci già la zona, parla con gli altri: forse hanno dei compiti per te.", "." },
  ["6df76b53fad40f34"] = { "Presto tutti gli Shen'dorei vedranno la verità... e chi rifiuterà sarà spazzato via dalla tempesta che sta arrivando!", "." },
  ["6dfe68c8eabab078"] = { "Tutto il pesce e il resto è in viaggio verso ⟦Silithus=Silitus⟧, e dovrebbe arrivare in meno di un giorno. Dopodiché qualcuno dovrà suonare quel gong con lo Scettro delle Sabbie Mutevoli per dare inizio alla guerra.", "." },
})
